mapper.select:
select c.* from review_cases c where c.type=#{type}
and (c.owner_id=#{userId} or c.supervisor_id=#{userId} or c.finance_id=#{userId}
or exists(select 1 from approval_delegation g where g.agent_id=#{userId} and g.type=c.type and g.dept_id=c.dept_id
and g.status='ACTIVE' and g.starts_at<=now() and g.ends_at>now() and c.status='IN_REVIEW'
and ((c.node='SUPERVISOR' and g.node=c.node and g.principal_id=c.supervisor_id) or (c.node='FINANCE' and g.node=c.node and g.principal_id=c.finance_id))))
order by c.updated_at desc,c.id desc

mapper.insert:
insert into review_config(type,target_key,dept_id,supervisor_id,finance_id,open_from,open_until)
values(#{type},#{targetKey},#{deptId},#{supervisorId},#{financeId},#{openFrom},#{openUntil})
on duplicate key update supervisor_id=#{supervisorId},finance_id=#{financeId},open_from=#{openFrom},open_until=#{openUntil}
